"""Password registration + login verification using OWASP-compliant hashing for new passwords.

New passwords:
- Use Argon2id (argon2-cffi) with OWASP minimum parameters:
  m=19456 KiB (19 MiB), t=2, p=1.

Legacy / stored passwords:
- Verify against any supported stored format (argon2id, scrypt, PBKDF2, bcrypt).
- Verification of older formats is always permitted.
"""

from __future__ import annotations

import argon2

import bcrypt_hasher as _bcrypt
import pbkdf2_hasher as _pbkdf2
import scrypt_hasher as _scrypt


# OWASP Password Storage Cheat Sheet as of 2024-12-09 (requires minimum Argon2id m=19 MiB, t=2, p=1)
# argon2-cffi uses memory_cost in KiB.
_ARGON2ID_HASHER = argon2.PasswordHasher(time_cost=2, memory_cost=19456, parallelism=1)


def register_password(password: str) -> str:
    """Return a string suitable for storing as the hash of a newly registered user's password."""
    # Delegate parameter-safe hashing to argon2-cffi with OWASP-minimum parameters.
    return _ARGON2ID_HASHER.hash(password)


def check_login(password: str, stored: str) -> bool:
    """Verify a login attempt against any supported stored hash format."""
    if not stored:
        return False

    # PBKDF2 hashes
    if stored.startswith("$pbkdf2-"):
        return _pbkdf2.verify_pbkdf2(password, stored)

    # Argon2id (PHC strings start with $argon2*)
    if stored.startswith("$argon2"):
        try:
            return argon2.PasswordHasher().verify(stored, password)
        except (argon2.exceptions.VerificationError, argon2.exceptions.InvalidHash, ValueError):
            return False

    # scrypt hashes
    if stored.startswith("$scrypt$"):
        return _scrypt.verify_scrypt(password, stored)

    # bcrypt hashes
    if stored.startswith(("$2a$", "$2b$", "$2y$")):
        return _bcrypt.verify_bcrypt(password, stored)

    return False
